# Refit locations per (check,segment) by MLE given df, scale
DF=1.05
scale={'bureau':52.5,'income':31.7,'bank':33.7}
best_loc={}
for ch in data:
    best_loc[ch]={}
    for s in segs:
        d=np.array(data[ch][s])
        def nll1(mu): return -np.sum(stats.t.logpdf(d,DF,mu,scale[ch]))
        rr=optimize.minimize_scalar(nll1, bounds=(200,1200), method='bounded')
        best_loc[ch][s]=rr.x
print('DF',DF)
for ch in data:
    print(ch, {s:round(best_loc[ch][s],1) for s in segs})

# band probabilities and likelihood tables (bands edges)
edges=[560,630,690,750,820]
def band_of(x):
    for i,e in enumerate(edges):
        if x<e: return i
    return 5
def band_probs(mu,ch):
    cdf=[stats.t.cdf(e,DF,mu,scale[ch]) for e in edges]
    p=[cdf[0]]+[cdf[i]-cdf[i-1] for i in range(1,5)]+[1-cdf[-1]]
    return np.clip(p,1e-9,1)
# sanity: observed band dist vs model for one
for ch in data:
    print('---',ch)
    for s in segs:
        obs=np.array([band_of(x) for x in data[ch][s]])
        print(s,'obs',np.bincount(obs,minlength=6), 'mu',round(best_loc[ch][s],1))
np.save('/tmp/locs.npy',best_loc,allow_pickle=True)
